<?php require '../includes/functions.php';$u=guard('admin');$title='Community accounts';require '../includes/header.php';?><div class="workspace"><?php require '../includes/sidebar.php';?><section class="workspace-content"><h1>Community accounts</h1><p>Review organisation details before approving an account.</p><form class="filter panel" method="get"><label>Search name, email or city<input name="q" value="<?=e($_GET['q']??'')?>"></label><label>Status<select name="status"><option value="">All accounts</option><?php foreach(['pending','approved','rejected'] as $s):?><option value="<?=$s?>" <?=($_GET['status']??'')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label><button class="button">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Organisation / person</th><th>Role</th><th>Contact & address</th><th>Status</th><th>Review</th></tr></thead><tbody><?php $q='%'.($_GET['q']??'').'%';$s=$_GET['status']??'';foreach(query("SELECT * FROM users WHERE role<>'admin' AND (name LIKE ? OR email LIKE ? OR city LIKE ?) AND (?='' OR status=?) ORDER BY status='pending' DESC,id DESC",[$q,$q,$q,$s,$s])->fetchAll() as $a):?><tr><td><b><?=e($a['name'])?></b><small><?=e($a['email'])?></small></td><td><?=e($a['role'])?></td><td><?=e($a['phone'])?><small><?=e($a['address'].', '.$a['city'])?></small></td><td><span class="badge <?=e($a['status'])?>"><?=e(ucfirst($a['status']))?></span></td><td><form method="post" action="<?=url('actions/admin-actions.php')?>"><?=csrf()?><input type="hidden" name="id" value="<?=$a['id']?>"><button class="button small" name="action" value="approve">Approve</button><button class="plain" name="action" value="reject" data-confirm="Reject this account? Active collections must be resolved first.">Reject</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require '../includes/footer.php';?>